import { ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Table as AntdTable, type TableProps } from 'antd';
import type { TablePaginationConfig } from 'antd/es/table';
import { FilterValue, SorterResult } from 'antd/es/table/interface';

import { CONFIG } from 'features/Pagination/config/config';
import { useMedia } from 'shared/hooks';
import { ESortOrder, ETableSearchParams } from 'shared/typings';
import { NoResults } from 'shared/ui';

interface ITableProps<T> extends Partial<TableProps<T>> {
	className?: string;
	dataCount: number | undefined;
	hasPagination?: boolean;
	isFirstLoading?: boolean;
	limit?: number;
}

export const Table = <T extends {}>({
	className,
	columns,
	dataCount = 0,
	dataSource,
	hasPagination = true,
	isFirstLoading,
	loading,
	limit,
	...props
}: ITableProps<T>): ReactNode => {
	const { t } = useTranslation();
	const [searchParams, setSearchParams] = useSearchParams();
	const isDesktop = useMedia('desktop');
	const defaultPerPage = limit || 15;

	const paginationConfig: TablePaginationConfig = {
		position: isDesktop ? ['bottomLeft'] : ['bottomCenter'],
		pageSizeOptions: [15, 50, 100],
		total: dataCount,
		pageSize: Number(searchParams.get(ETableSearchParams.LIMIT)) || defaultPerPage,
		current:
			Math.floor(
				Number(searchParams.get(ETableSearchParams.OFFSET) || 0) /
					(Number(searchParams.get(ETableSearchParams.LIMIT)) || defaultPerPage),
			) + 1,
		showSizeChanger: true,
		showQuickJumper: false,
		showTotal: isDesktop ? (total) => t('Total {{count}} items', { count: total }) : undefined,
	};

	const handlePagination = (pagination: TablePaginationConfig) => {
		const newPerPage = limit || pagination.pageSize || CONFIG.PER_PAGE;
		const newPageNumber = pagination.current || 1;
		const newOffsetIndex = newPerPage * (newPageNumber - 1);

		searchParams.set(ETableSearchParams.LIMIT, newPerPage.toString());
		searchParams.set(ETableSearchParams.OFFSET, newOffsetIndex.toString());
		setSearchParams(searchParams);
	};

	const handleSort = (sorter: SorterResult | SorterResult[]) => {
		if (Object.keys(sorter).length) {
			const sort = sorter as SorterResult;
			sort.field
				? searchParams.set(ETableSearchParams.ORDERING, `${sort.order === ESortOrder.DESC ? '-' : ''}${sort.field}`)
				: searchParams.delete(ETableSearchParams.ORDERING);
			searchParams.delete(ETableSearchParams.OFFSET);
		}
		if (limit) {
			searchParams.set(ETableSearchParams.LIMIT, limit.toString());
		}
		setSearchParams(searchParams);
	};

	const handleTableChange: TableProps<T>['onChange'] = (
		pagination: TablePaginationConfig,
		_: Record<string, FilterValue | null>,
		sorter: SorterResult<T> | SorterResult<T>[],
	) => {
		if (sorter) {
			handleSort(sorter);
		}
		handlePagination(pagination);
	};

	return (
		<AntdTable
			className={className}
			columns={columns}
			dataSource={dataSource}
			loading={loading}
			locale={{
				emptyText: !isFirstLoading && <NoResults />,
			}}
			onChange={handleTableChange}
			pagination={hasPagination && paginationConfig}
			rowKey={'uuid'}
			scroll={{ x: 'max-content' }}
			size={'middle'}
			{...props}
		/>
	);
};
